/**
 * ⌘F find/replace panel: localization and positioning config for @codemirror/search's built-in panel.
 *
 * The panel DOM is generated by @codemirror/search itself (its structure can't change), so only two things can be adjusted:
 * 1) phrases: every visible string goes through `state.phrase()`, so injecting translations localizes the whole panel
 *    (Chinese source goes through t(), and the English UI gets English from the dictionary; on language switch it's reconfigured via a compartment and applies next time the panel opens);
 * 2) styles: see the find/replace panel section in app/editor.css, all on theme variables, shared by light and dark.
 * So this only handles "which extensions + what text"; visuals stay in CSS, each side minding its own.
 */

import { Compartment, EditorState, type Extension } from "@codemirror/state";
import { ViewPlugin, type EditorView } from "@codemirror/view";
import { highlightSelectionMatches, search } from "@codemirror/search";
import { t, tk } from "@/i18n/t";
import { LOCALE_CHANGED_EVENT } from "@/i18n/locale";

/**
 * Every phrase @codemirror/search uses. Keys must match the English source text exactly
 * (see the `phrase(view, ...)` calls in node_modules/@codemirror/search/dist/index.js);
 * missing one leaves an English word showing on the panel. `$` is the official placeholder and must be kept verbatim in translations.
 * Values store the Chinese source text (tk-marked) and go through t() at setup: the English UI also uses the dictionary, so button wording matches the rest of the product.
 */
const SEARCH_PHRASES: Record<string, string> = {
  // Visible on the panel: input placeholders, three buttons, three checkboxes, the close button
  Find: tk("查找"),
  Replace: tk("替换"),
  next: tk("下一个"),
  previous: tk("上一个"),
  all: tk("全选匹配"),
  "match case": tk("区分大小写"),
  regexp: tk("正则"),
  "by word": tk("全词匹配"),
  replace: tk("替换"),
  "replace all": tk("全部替换"),
  close: tk("关闭"),
  // Screen-reader announcements: broadcast by EditorView.announce when jumping to a match or after replacing
  "current match": tk("当前匹配"),
  "on line": tk("位于第"),
  "replaced match on line $": tk("已替换第 $ 行的一处匹配"),
  "replaced $ matches": tk("已替换 $ 处匹配"),
  // ⌘⌥G go-to-line dialog
  "Go to line": tk("跳转到行"),
  go: tk("跳转"),
};

/** Translate the phrase table for the current language; read inside a function, since fixing it at module load wouldn't follow language switches */
function phrasesNow(): Extension {
  const out: Record<string, string> = {};
  for (const [k, v] of Object.entries(SEARCH_PHRASES)) out[k] = t(v);
  return EditorState.phrases.of(out);
}

const phrasesCompartment = new Compartment();

/** Reconfigure phrases on UI language switch: an already-open panel isn't force-refreshed; close and reopen (or ⌘F) for the new language */
const localeSync = ViewPlugin.fromClass(
  class {
    private readonly onChange: () => void;
    constructor(view: EditorView) {
      this.onChange = () => view.dispatch({ effects: phrasesCompartment.reconfigure(phrasesNow()) });
      window.addEventListener(LOCALE_CHANGED_EVENT, this.onChange);
    }
    destroy() {
      window.removeEventListener(LOCALE_CHANGED_EVENT, this.onChange);
    }
  }
);

/**
 * Set up the search extension.
 * - top: true: the panel sits at the top of the editor. At the bottom it would hug the window's lower edge in the home document view,
 *   far from the text and cursor; at the top, combined with CSS sticky, it stays in view.
 * - highlightSelectionMatches: select some text and identical fragments in the body get a faint highlight.
 *   Threshold raised to 2 chars: selecting a single char (especially Chinese) lights up almost the whole page, which is distracting;
 *   highlightWordAroundCursor stays off, so only "actually selected text" counts, without guessing the word near the cursor.
 */
export function editorSearch(): Extension[] {
  return [
    search({ top: true }),
    highlightSelectionMatches({ minSelectionLength: 2, highlightWordAroundCursor: false }),
    // Read the current language each time an editor is built: a module constant would be fixed at load time
    phrasesCompartment.of(phrasesNow()),
    localeSync,
  ];
}
